targets.query:
// A rate per window from the bytes and seconds in it: a mean of per-interval rates
// would let the sub-second interval a restart leaves behind spike the chart.
from(bucket:"smokeping") |> range(start:v.timeRangeStart, stop:v.timeRangeStop)
  |> filter(fn:(r) => r._measurement == "service_traffic" and (r._field == "rx_bytes" or r._field == "tx_bytes" or r._field == "seconds"))
  // One kind per service (meter.py): grouping it away cannot sum a service's seconds twice.
  |> group(columns:["service", "_field"])
  // An interval is stamped at its end, so the window it falls in starts about where its
  // bytes ended: "_start" puts the rate there, "_stop" would put it a window later.
  |> aggregateWindow(every: v.windowPeriod, fn: sum, createEmpty: false, timeSrc: "_start")
  |> pivot(rowKey:["_time"], columnKey:["_field"], valueColumn:"_value")
  |> filter(fn:(r) => exists r.rx_bytes and exists r.tx_bytes and exists r.seconds and r.seconds >= 60.0)
  |> map(fn:(r) => ({_time: r._time, service: r.service, _value: float(v: r.rx_bytes + r.tx_bytes) * 8.0 / r.seconds}))

// A rate per window from the bytes and seconds in it: a mean of per-interval rates
// would let the sub-second interval a restart leaves behind spike the chart.
from(bucket:"smokeping") |> range(start:v.timeRangeStart, stop:v.timeRangeStop)
  |> filter(fn:(r) => r._measurement == "uplink_traffic" and (r._field == "rx_bytes" or r._field == "tx_bytes" or r._field == "seconds"))
  |> group(columns:["_field"])
  // An interval is stamped at its end, so the window it falls in starts about where its
  // bytes ended: "_start" puts the rate there, "_stop" would put it a window later.
  |> aggregateWindow(every: v.windowPeriod, fn: sum, createEmpty: false, timeSrc: "_start")
  |> pivot(rowKey:["_time"], columnKey:["_field"], valueColumn:"_value")
  |> filter(fn:(r) => exists r.rx_bytes and exists r.tx_bytes and exists r.seconds and r.seconds >= 60.0)
  |> map(fn:(r) => ({_time: r._time, _value: float(v: r.rx_bytes + r.tx_bytes) * 8.0 / r.seconds}))
